%%Emilijus Gureckas
%LD 4, 3 var.
%%
x = linspace(-1,1,50);
y = linspace(-1,1,50);

[X,Y] = meshgrid(x,y);

R = sqrt(X.^2 + Y.^2);
Z = exp(R.^2);

figure %[output:25be0edb]
h = surf(X,Y,Z); %[output:25be0edb]

shading interp %[output:25be0edb]
colormap parula %[output:25be0edb]

rotate(h,[1 0 0],10) %[output:25be0edb]
rotate(h,[0 1 0],10) %[output:25be0edb]

xlabel('x') %[output:25be0edb]
ylabel('y') %[output:25be0edb]
zlabel('z') %[output:25be0edb]
title('z(r) = e^{r^2}') %[output:25be0edb]

grid on %[output:25be0edb]

x = linspace(-2,2,20);
y = linspace(-2,2,20);
z = linspace(-1,1,20);

[X,Y,Z] = meshgrid(x,y,z);

F = sin((X.^2 + Y.^2)/20).*exp(-(X.^2 + Y.^2));

figure %[output:22ec1233]

h = slice(X,Y,Z,F,[-1 0 1],[-1 0 1],[-0.5 0 0.5]); %[output:22ec1233]

shading interp %[output:22ec1233]
colormap parula %[output:22ec1233]

rotate(h,[1 0 0],15) %[output:22ec1233]
rotate(h,[0 1 0],15) %[output:22ec1233]

xlabel('x') %[output:22ec1233]
ylabel('y') %[output:22ec1233]
zlabel('z') %[output:22ec1233]
title('f(x,y) = sin((x^2+y^2)/20)e^{-(x^2+y^2)}') %[output:22ec1233]

grid on %[output:22ec1233]

